INSERT INTO "laminas" VALUES(1,'pra2-lamina-1','pra2.html',0,'I','Patología Celular','adaptacion-celular','Adaptación Celular','Metaplasia Intestinal','METAPLASIA',NULL,NULL,NULL,NULL,'Varón de 73 años, biopsia de esófago','Reflujo gastroesofágico persistente','[{"value": "Esofagoscopia: cambios en mucosa esofágica", "url": null}]','[]','["¿Qué características morfológicas asociadas a metaplasia reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "Investigue cómo podría progresar esta alteración"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEQA%2FGeneral_Histopathology%2FHisto_EQA_CircAK%2F415979.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MHS-234-esophagus/14-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/gerd.html"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/multimedia/image/barrett-esophagus"}]',0,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(2,'pra2-lamina-2','pra2.html',1,'I','Patología Celular','adaptacion-celular','Adaptación Celular','Atrofia Vellositaria','ATROFIA',NULL,NULL,NULL,NULL,'Mujer de 29 años, biopsia de yeyuno','Fatiga, pérdida de peso, diarrea tras consumo de gluten','[{"value": "Anticuerpos anti-transglutaminasa elevados", "url": null}]','[]','["¿Qué características morfológicas asociadas a atrofia reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "Investigue cómo podría progresar esta alteración"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FMFD_GI%2FJejunum%2F7896.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MHS-219-jejunum/14-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/celiac-disease-screening/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/gastrointestinal-disorders/malabsorption-syndromes/celiac-disease?query=celiac"}]',1,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(3,'pra2-lamina-3','pra2.html',2,'I','Patología Celular','adaptacion-celular','Adaptación Celular','Hiperplasia Prostática','HIPERPLASIA',NULL,NULL,NULL,NULL,'Varón de 70 años, biopsia de próstata','Dificultad para iniciar micción, chorro débil, nicturia','[{"value": "PSA: 8.2 ng/mL (Normal: <4 ng/mL)", "url": null}]','[]','["¿Qué características morfológicas asociadas a hiperplasia reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "Investigue cómo podría progresar esta alteración"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1119.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-183-prostate/19-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/prostate-specific-antigen-psa-test/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/genitourinary-disorders/benign-prostate-disease/benign-prostatic-hyperplasia?query=pbh"}]',2,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(4,'pra2-lamina-4','pra2.html',3,'I','Patología Celular','adaptacion-celular','Adaptación Celular','Hipertrofia Muscular','HIPERTROFIA',NULL,NULL,NULL,NULL,'Niño de 8 años, biopsia de músculo','Retraso motor, debilidad proximal, hipertrofia leve de pantorrillas, problemas respiratorios','[{"value": "Creatina quinasa (CK) > 8000 U/L (Normal: 39-308 U/L), ", "url": null}]','[]','["¿Qué características morfológicas asociadas a hipertrofia reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "Investigue cómo podría progresar esta alteración"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FNeuropathology%2FMuscle_and_Nerve_pathology%2FDystrophy%2F319748.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-055a-skeletal-muscle/04-slide-1.html?b=ax1x1x3x35783x41961x-1"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/creatine-kinase/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/pediatrics/inherited-muscular-disorders/duchenne-muscular-dystrophy-and-becker-muscular-dystrophy?query=becker#Treatment_v12784711"}]',3,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(5,'pra3-lamina-1','pra3.html',0,'I','Patología Celular','lesion-celular','Lesión Celular','Esteatosis hepática','ESTEATOSIS',NULL,NULL,NULL,NULL,'Varón de 61 años, bebedor social, obesidad.','Dolor en cuadrante superior derecho','[{"value": "Alanina transaminasa: 120 U/L (Normal: 7-56 U/L)", "url": null}]','[]','["¿Qué características morfológicas asociadas a esteatosis reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "Investigue cómo podría progresar esta alteración"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FSlide_Library%2FLiver%2F36859.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-126b-liver/15-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/alt-blood-test/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/hepatic-and-biliary-disorders/approach-to-the-patient-with-liver-disease/metabolic-dysfunction-associated-liver-disease-masld?query=steatosis%20of%20livers"}]',4,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(6,'pra3-lamina-2','pra3.html',1,'I','Patología Celular','lesion-celular','Lesión Celular','Lesión renal aguda','EDEMA CELULAR',NULL,NULL,NULL,NULL,'Mujer de 45 años en dialisis, biopsia de corteza renal','Lesión renal aguda tras TAC con contraste, oliguria','[{"value": "Creatinina: 4.2 mg/dL (previo: 1.1 mg/dL)", "url": null}]','[]','["¿Qué características morfológicas asociadas a edema celular reconoce?", "Relacione los hallazgos morfológicos con el contexto clínico", "¿Cree que este daño puede revertirse? Justifique su respuesta"]','[{"label": "Caso Clínico", "url": "https://virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FPostgraduate%2FSets%2FRenal%2FMaster%2FNatives%2FRN15%2F208624.svs"}, {"label": "Histología Referencia", "url": "https://www.histologyguide.com/slideview/MH-143-kidney/16-slide-1.html?x=19618&y=45744&z=6.3"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/creatinine-test/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/genitourinary-disorders/acute-kidney-injury/acute-kidney-injury-aki?query=acute%20renal%20injury"}]',5,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(7,'pra3-lamina-3','pra3.html',2,'I','Patología Celular','lesion-celular','Lesión Celular','Antracosis Pulmonar','PIGMENTOS PATOLÓGICOS',NULL,NULL,NULL,NULL,'Hombre de 67 años, trabajador industrial y minero jubilado','Disnea de esfuerzo, tos crónica no productiva','[{"value": "Radiografía: opacidades pulmonares, función pulmonar alterada", "url": null}]','[]','["¿Qué tipo de pigmento observa? Describa sus características morfológicas.", "¿En que tipo celular se acumula? ¿Por qué esta acumulación es irreversible?", "¿Cómo se relaciona con la historia laboral del paciente?"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEQA%2FGeneral_Histopathology%2FHisto_EQA_CircZ_Set6%2F205288.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-138-lung/17-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/ency/imagepages/1601.htm"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/pulmonary-disorders/environmental-and-occupational-pulmonary-diseases/coal-worker-pneumoconiosis?query=anthracosis"}]',6,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(8,'pra4-lamina-1','pra4.html',0,'I','Patología Celular','muerte-celular','Muerte Celular','Infarto Renal','NECROSIS COAGULATIVA',NULL,NULL,NULL,NULL,'Varón de 55 años, hospitalizado por falla renal.','HTA de 10 años, mal controlada. Falla renal aguda dos semanas posteriores a un infarto al miocardio tratado con trombólisis y stent.','[{"value": "Creatinina sérica: 3.5 mg/dL (valor de referencia: 0.6-1.2 mg/dL), Urea sérica: 45 mg/dL (valor de referencia: 7-20 mg/dL).", "url": null}]','[]','["¿Qué características morfológicas asociadas a necrosis coagulativa reconoce?", "Describa el mecanismo fisiopatológico asociado a este caso particular"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1111.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-141b-kidney/16-slide-1.html?x=23905&y=16102&z=9.30"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/bun-blood-urea-nitrogen/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/genitourinary-disorders/acute-kidney-injury/acute-kidney-injury-aki"}]',7,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(9,'pra4-lamina-2','pra4.html',1,'I','Patología Celular','muerte-celular','Muerte Celular','Hepatotoxicidad','NECROSIS COAGULATIVA',NULL,NULL,NULL,NULL,'Mujer de 35 años, hospitalizada por falla hepática','Antecedentes de depresión no tratada. Presenta ictericia  y dolor en el cuadrante superior derecho del abdomen tras sobredosis intencional con paracetamol.','[{"value": "Aspartato Transaminasa (AST): 1,200 U/L (valor normal: 10-40 U/L), Alanina Transaminasa (ALT): 1,500 U/L (valor normal: 7-56 U/L), Bilirrubina total: 8 mg/dL (valor normal: 0.1-1.2 mg/dL).", "url": null}]','[]','["¿Qué características morfológicas asociadas a necrosis coagulativa reconoce?", "Describa el mecanismo fisiopatológico asociado a este caso particular"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1061.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-126b-liver/15-slide-1.html?x=30667&y=15752&z=15.90"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/bilirubin-blood-test/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/injuries-poisoning/poisoning/acetaminophen-poisoning?query=paracetamol"}]',8,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(10,'pra4-lamina-3','pra4.html',2,'I','Patología Celular','muerte-celular','Muerte Celular','Tuberculosis Pulmonar','NECROSIS CASEOSA',NULL,NULL,NULL,NULL,'Hombre de 60 años, fumador','Presenta tos persistente, fiebre, pérdida de peso y sudores nocturnos.','[{"value": "Radiografía de tórax muestra múltiples lesiones pequeñas de distribución uniforme, prueba de tuberculina PPD - Positiva, Resultados de cultivo de esputo en espera.", "url": null}]','[]','["¿Qué características morfológicas asociadas a necrosis caseosa reconoce?", "Describa el mecanismo fisiopatológico asociado a este caso particular"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1104.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-138-lung/17-slide-1.html?x=24212&y=14372&z=4.5"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/tuberculosis-screening/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/infectious-diseases/mycobacteria/tuberculosis-tb?query=tuberculosis"}]',9,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(11,'pra5-lamina-1','pra5.html',0,'II','Inflamación','inflamacion-aguda-cronica','Inflamación Aguda y Crónica','Apendicitis Aguda','INFLAMACIÓN AGUDA',NULL,NULL,NULL,NULL,'Varón de 20 años, sin antecedentes médicos de importancia.','Acude a urgencias por dolor abdominal localizado inicialmente en la región periumbilical, que en las últimas horas se ha desplazado al cuadrante inferior derecho. El dolor se acompaña de náuseas, vómitos y fiebre de 38.5°C.','[{"value": "Hemograma: Neutrófilos 14,000/µL (vr: 4,000-11,000/µL). Proteína C reactiva (PCR): 25 mg/L (vr: <5 mg/L). Ecografía abdominal: Apéndice no compresible, con diámetro de 8 mm, acompañado de aumento de la ecogenicidad del tejido graso periapendicular. No se observan fecalitos.", "url": null}]','[]','["¿Qué características morfológicas asociadas a inflamación aguda reconoce?", "Describa el mecanismo fisiopatológico asociado a este caso particular"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FMFD_GI%2FAppendix%2F9143.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-122-appendix/14-slide-1.html"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/ency/article/003356.htm"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/gastrointestinal-disorders/acute-abdomen-and-surgical-gastroenterology/appendicitis?query=appendicitis"}]',10,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(12,'pra5-lamina-2','pra5.html',1,'II','Inflamación','inflamacion-aguda-cronica','Inflamación Aguda y Crónica','Cirrosis hepática','INFLAMACIÓN CRÓNICA',NULL,NULL,NULL,NULL,'Mujer de 47 años. Antecedentes de hepatitis B crónica diagnosticada hace 20 años y transplante ortotópico','Presenta fatiga, ictericia progresiva y molestias abdominales en el cuadrante superior derecho durante los últimos seis meses. Sin antecedentes de consumo problemático de alcohol ni obesidad.','[{"value": "Bilirrubina total 3.2 mg/dL (vr: 0.1-1.2 mg/dL), AST 85 U/L (vr: 10-40 U/L), ALT 78 U/L (vr: 7-56 U/L), Albúmina 2.8 g/dL (vr: 3.5-5.0 g/dL)., INR: 1.6 (vr: 0.8-1.2)., Ecografía abdominal: Hígado de contornos irregulares con aumento de la ecogenicidad, signos de hipertensión portal, y esplenomegalia.", "url": null}]','[]','["¿Qué características morfológicas asociadas a inflamación crónica reconoce?", "Describa el mecanismo fisiopatológico asociado a este caso particular"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1061.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-126b-liver/15-slide-1.html?x=30667&y=15752&z=15.90"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/prothrombin-time-test-and-inr-ptinr/"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/hepatic-and-biliary-disorders/hepatitis/hepatitis-b-chronic"}]',11,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(13,'pra6-lamina-1','pra6.html',0,'III','Neoplasias','neoplasias-benignas','Neoplasias Benignas','Fibroadenoma de mama','NEOPLASIA BENIGNA FIBROEPITELIAL',NULL,NULL,NULL,NULL,'Mujer de 28 años, madre de lactante de 14 meses.','Nódulo palpable en cuadrante superoexterno de mama izquierda, móvil, bien delimitado, no doloroso. Aparición hace 8 meses con crecimiento lento progresivo','[{"value": "Mamografía: nódulo bien circunscrito. Ecografía: masa hipoecogénica homogénea con márgenes regulares.", "url": null}]','[]','["Describa las características histológicas de esta muestra ¿Qué componentes tisulares identifica?", "Identifique las características de benignidad presentes en la muestra", "Relacione los hallazgos microscópicos con las características clínicas y de imagen"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEQA%2FGeneral_Histopathology%2FHisto_EQA_CircU%2F125127.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-174a-mammary-gland/18-slide-1.html?x=11961&y=17023&z=2.62"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/ency/article/007216.htm"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/gynecology-and-obstetrics/breast-disorders/breast-masses-breast-lumps?query=fibroadenoma"}]',12,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(14,'pra6-lamina-2','pra6.html',1,'III','Neoplasias','neoplasias-benignas','Neoplasias Benignas','Polipo adenomatoso','NEOPLASIA BENIGNA EPITELIAL',NULL,NULL,NULL,NULL,'Mujer de 49 años','Dolor abdominal intermitente, distensión abdominal, cambios en hábito intestinal con diarrea alternada con estreñimiento. Pérdida de peso de 4 kg en 6 meses. Heces más delgadas de lo normal.','[{"value": "Colonoscopía: lesión obstructiva en flexura esplénica del colon + múltiples pólipos distribuidos en todo el colon.", "url": null}]','[]','["Describa las características histológicas de esta muestra ¿Qué características de benignidad logra observar?", "Relacione los antecedentes clínicos de este paciente con los hallazgos observados en la muestra", "¿Qué estudio genético sería relevante realizar en este caso?", "¿Qué complicaciones podría desarrollar este paciente?"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FMFD_GI%2FColon%2F6334.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-123-colon/14-slide-1.html?x=32225&y=8989&z=3.30"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/colonicpolyps.html"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/professional/gastrointestinal-disorders/tumors-of-the-gastrointestinal-tract/familial-adenomatous-polyposis?query=poliposis%20adenomatosa%20familiar"}]',13,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(15,'pra6-lamina-3','pra6.html',2,'III','Neoplasias','neoplasias-benignas','Neoplasias Benignas','Leiomioma Cutáneo','NEOPLASIA BENIGNA DE MÚSCULO LISO',NULL,NULL,NULL,NULL,'Hombre de 25 años. Antecedentes familiares de leiomioma uterino (madre)','Biopsia excisional de nódulo cutáneo doloroso en pierna derecha. Nódulo móvil al examen físico. Sin cambios de coloración, sangrado, ulceración o prurito. Antecedentes de nódulos cutáneos desde los 15 años. Paciente niega síntomas sistémicos como fiebre, pérdida de peso o malestar general','[{"value": "Resultados de pruebas genéticas en espera", "url": null}]','[]','["Describa las características histológicas de esta muestra ¿Qué características de benignidad logra observar?", "Relacione los antecedentes clínicos de este paciente con los hallazgos observados en la muestra", "¿Qué test genético se le ordenó al paciente?", "¿Qué complicaciones podría desarrollar este paciente?"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEQA%2FSkin%2FBSD_self_assessment%2F2014_06_30%2F256160.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-090-thin-skin/11-slide-1.html?x=13296&y=4184&z=29.80"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/genetics/condition/hereditary-leiomyomatosis-and-renal-cell-cancer/#resources"}, {"label": "MSD Manuals", "url": "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hlrcc"}]',14,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(16,'pra7-lamina-1','pra7.html',0,'III','Neoplasias','neoplasias-malignas','Neoplasias Malignas','Adenocarcinoma de colon','NEOPLASIA MALIGNA EPITELIAL',NULL,NULL,NULL,NULL,'Hombre de 60 años','Presenta dolor abdominal persistente, acompañado de cambios en el hábito intestinal en los últimos meses, con predominio de estreñimiento. Ha experimentado una pérdida de peso de 5 kg en los últimos 4 meses sin modificaciones en su dieta.','[{"value": "Colonoscopía: lesión infiltrativa. Análisis genético: Mutación G12D en KRAS", "url": null}]','[]','["Describa las características histológicas de esta muestra ¿Qué características de malignidad logra observar?", "Compare con la lámina del pólipo adenomatoso, que diferencias relevantes observa", "Investigue la función de KRAS y explique la importancia de su estudio en el cancer de colon"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FUndergraduate%2F1485.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-123-colon/14-slide-1.html?x=32225&y=8989&z=3.30"}, {"label": "MedlinePlus", "url": "https://medlineplus.gov/lab-tests/fecal-occult-blood-test-fobt/"}, {"label": "MSD Manuals", "url": "https://bpsbioscience.com/research-areas/ras"}]',15,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(17,'pra7-lamina-2','pra7.html',1,'III','Neoplasias','neoplasias-malignas','Neoplasias Malignas','Leiomiosarcoma cutáneo grado 1','NEOPLASIA MALIGNA DE MÚSCULO LISO',NULL,NULL,NULL,NULL,'Hombre de 39 años.','Biopsia excisional de masa sospechosa, no móvil, localizada en hombro izquierdo','[{"value": "Se solicita estudio de inmunohistoquímica (IHQ)", "url": null}]','[]','["Describa las características histológicas de esta muestra ¿Qué características de malignidad logra observar?", "Compare con la lámina del leiomioma, que diferencias relevantes observa", "¿Qué significa que este tumor sea de grado histológico 1?", "¿Cuál es el origen histológico de este tumor? Indique un marcador de IHQ que permita demostrarlo"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FSlide_Library%2FSara_Edward%2FSet_6%2F122820.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-090-thin-skin/11-slide-1.html?x=13296&y=4184&z=29.80"}, {"label": "PathologyOutlines", "url": "https://www.pathologyoutlines.com/topic/softtissuesmoothmuscle.html"}, {"label": "National Cancer Institute", "url": "https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}]',16,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(18,'pra8-lamina-1','pra8.html',0,'IV','Trastornos Circulatorios','trombosis-infarto','Trombosis e Infarto','Cerebro','ACV',NULL,NULL,NULL,NULL,'Mujer de 53 años de edad. Presento dolor de cabeza de comienzo suave hasta convertirse en insoportable y punzante, de acuerdo con su relato','La paciente relata hipertensión arterial y dislipidemia, las que controla pobremenTe con dieta y farmacos. Su marido relata qu e se encuentra tomando haciendo dieta y tomando unas pastillas para bajar de peso, las qué resultan contener fentermina.','[{"value": "AngioCT en estudio", "url": null}]','[]','["Describa la etiología de la lesión", "Carácterísticas del cuadro clínico", "Características histopatológicas de este infarto, indicando aquellas que más lo distinguen deDetalle las principales diferencias de los tipos de ateromas", "Respecto del proceso de reparación del tejido, describa el mecanismo más relevante y su resultado"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FNeuropathology%2FVascular_diseases%2F438110.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MHS-283-brain/06-slide-1.html?x=31289&y=7644&z=25.0"}, {"label": "MedlinePlus", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4011567/"}, {"label": "MSD Manuals", "url": "https://www.radiologyinfo.org/es/info/angioct"}]',17,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "laminas" VALUES(19,'pra8-lamina-2','pra8.html',1,'IV','Trastornos Circulatorios','trombosis-infarto','Trombosis e Infarto','Aorta Abdominal','ATEROMA',NULL,NULL,NULL,NULL,'Hombre de 61 años de edad. Presenta vértigo acompañado de náuseas y vómitos.','El dolor inicio aproximadamente 6 horas de forma repentina e intensa que varía entre la zona abdominal y costados.','[{"value": "Resonancia magnética: Trombosis por placa ateromatosa de aorta abdominal", "url": null}]','[]','["Describa la etiología de la lesión", "Mencione las características histopatológica del cuadro clínico", "Detalle las principales diferencias de los tipos de ateromas", "Mencione cronológicamente los mecanismos de reparación de la lesión"]','[{"label": "Caso Clínico", "url": "https://www.virtualpathology.leeds.ac.uk/slides/library/view.php?path=%2FResearch_4%2FTeaching%2FEducation%2FTeaching%2FNeuropathology%2FVascular_diseases%2F438085.svs"}, {"label": "Histología Referencia", "url": "https://histologyguide.com/slideview/MH-065-066-aorta-and-vena-cava/09-slide-1.html?x=46073&y=50180&z=10.0"}, {"label": "MedlinePlus", "url": "https://www.msdmanuals.com/es/professional/temas-especiales/principios-de-estudios-por-la-imagen-radiol%C3%B3gicas/resonancia-magn%C3%A9tica"}, {"label": "MSD Manuals", "url": "https://www.msdmanuals.com/es/professional/trastornos-cardiovasculares/arteriosclerosis/aterosclerosis"}]',18,'2026-08-06 17:44:50','2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(1,'pra1.html','01','Introducción','Introducción a la Patología Digital','🔬','Aprende los fundamentos del laboratorio de anatomía patológica y familiarízate con el proceso de obtención, procesamiento y observación de muestras histológicas. Descubre cómo la patología digital revoluciona el aprendizaje tradicional.',1,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(2,'pra2.html','02','Adaptación','Adaptación Celular','🔄','Explora los mecanismos de adaptación celular frente a estímulos diversos. Identifica cambios de hipertrofia, hiperplasia, atrofia y metaplasia en preparaciones histológicas reales y comprende su significado patológico.',2,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(3,'pra3.html','03','Lesión','Lesión Celular','⚠️','Reconoce los signos microscópicos de lesión celular reversible e irreversible. Estudia las alteraciones morfológicas que preceden a la muerte celular y comprende los mecanismos bioquímicos subyacentes.',3,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(4,'pra4.html','04','Muerte','Muerte Celular','💀','Diferencia los tipos de muerte celular: necrosis, apoptosis y autofagia. Identifica las características histológicas distintivas de cada tipo y comprende sus implicaciones clínicas y fisiopatológicas.',4,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(5,'pra5.html','05','Inflamación','Inflamación','🔥','Analiza el proceso inflamatorio agudo y crónico a nivel microscópico. Identifica los componentes celulares del infiltrado inflamatorio y comprende los patrones de respuesta tisular ante diferentes agresiones.',5,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(6,'pra6.html','06','Neoplasias Benignas','Neoplasias Benignas','🧬','Estudia las características histológicas de los tumores benignos. Aprende a diferenciarlos de tejidos normales, reconoce patrones de crecimiento organizados y comprende su comportamiento clínico favorable.',6,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(7,'pra7.html','07','Neoplasias Malignas','Neoplasias Malignas','☠️','Identifica las características de malignidad en preparaciones histológicas. Reconoce atipia celular, mitosis anormales, patrón de crecimiento invasivo y comprende los criterios diagnósticos de cáncer.',7,'2026-08-06 17:44:50');
INSERT INTO "practicos" VALUES(8,'pra8.html','08','Trombosis e Infarto','Trombosis e Infarto','🩸','Examina las alteraciones hemodinámicas y sus consecuencias tisulares. Identifica trombos, estudia la evolución del infarto y comprende los mecanismos de isquemia, necrosis y reparación vascular.',8,'2026-08-06 17:44:50');
